    FOREIGN KEY ("customFrameworkId") REFERENCES "CustomFramework"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- 2. Relax FK nullability on FrameworkInstance / RequirementMap so rows can point
--    at the new tables instead.
